describe('Login Form Validation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display error messages when required fields are empty', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Fill in only the username field
    cy.get('[data-testid="user-name"]').type('standard_user');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error"]').should('contain', 'Username is required');

    // Verify login button is disabled
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Verify error container is still visible
    cy.get('[data-testid="error"]').should('be.visible');
  });

  it('should display error messages when password field is empty', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in only the username field
    cy.get('[data-testid="user-name"]').type('standard_user');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error"]').should('contain', 'Password is required');

    // Verify login button is disabled
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Verify error container is still visible
    cy.get('[data-testid="error"]').should('be.visible');
  });

  it('should display error messages when both fields are empty', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Click login button with both fields empty
    cy.get('[data-testid="login-button"]').click();

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Verify error message contains both required fields
    cy.get('[data-testid="error"]').should('contain', 'Username is required');
    cy.get('[data-testid="error"]').should('contain', 'Password is required');

    // Verify login button is disabled
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Verify error container is still visible
    cy.get('[data-testid="error"]').should('be.visible');
  });
});
